import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { formatEuros, roundCents } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;
  const invoiceNumber = invoice.number ?? 'DRAFT';

  const lines = [];
  lines.push(invoiceNumber);
  lines.push(customer.name);

  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const discountPercent = line.discountPercent ?? 0;

    if (discountPercent > 0) {
      const discountAmount = roundCents((lineTotal * discountPercent) / 100);
      const discountedTotal = Math.max(0, lineTotal - discountAmount);
      lines.push(
        `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lineTotal)} (${discountPercent}% off: -${formatEuros(discountAmount)}) = ${formatEuros(discountedTotal)}`
      );
    } else {
      lines.push(
        `${line.qty} × ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lineTotal)}`
      );
    }
  }

  const totals = invoiceTotals(invoice);
  if (totals.discount > 0 || totals.vat > 0) {
    lines.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    if (totals.discount > 0) {
      lines.push(`Discount: -${formatEuros(totals.discount)}`);
    }
    if (totals.vat > 0) {
      lines.push(`VAT: +${formatEuros(totals.vat)}`);
    }
  }
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return ok(lines.join('\n'));
}

